values ('property-management-administration-australia','Property Management Administration Australia','Australian property-management administration training for Filipino VAs covering owner and tenant records, leasing enquiries, applications, rent admin, maintenance, contractors, inspections, access, renewals, vacates, bond boundaries, and local-jurisdiction escalation.','industry','Australia',240,25,'draft',1,null,null,null,now(),now())
