insert into public.training_modules (course_id,title,summary,position) values ((select id from public.training_courses where slug='property-management-administration-australia'),'Property Management Foundations','Understand roles, records, and leasing boundaries.',1) on conflict (course_id,position) do update set title=excluded.title,summary=excluded.summary,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='property-management-administration-australia') and position=1),'australian-property-management-operating-model-and-va-boundaries','Australian Property Management Operating Model and VA Boundaries','Property management combines owner service, tenant communication, leasing, rent administration, maintenance, inspections, notices, contractors, records, and legal obligations. A VA can coordinate administration, but state and territory tenancy rules and licensed decisions must stay with responsible staff.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Understand common property-management roles","Map the tenancy lifecycle","Separate admin support from licensed or legal decisions"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Property management combines owner service, tenant communication, leasing, rent administration, maintenance, inspections, notices, contractors, records, and legal obligations. A VA can coordinate administration, but state and territory tenancy rules and licensed decisions must stay with responsible staff."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["A property manager acts for the owner within agency and tenancy rules.","Tenants, owners, contractors, leasing staff, trust/accounts staff, and property managers have different authority.","The lifecycle can include listing, enquiry, application, tenancy setup, rent, maintenance, inspections, renewal, vacate, bond, and archive.","State and territory laws differ.","A VA should use the agency''s local SOP, forms, and escalation contacts."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Identify the state or territory and agency location.","Map portfolio roles and decision owners.","Identify source systems for properties, tenants, owners, inspections, maintenance, rent, and documents.","List routine VA tasks.","List licensed, trust, legal, tenancy, rent, notice, and dispute decisions that require local staff.","Document escalation."]},{"type":"callout","title":"Stay inside the role","text":"Do not interpret tenancy legislation, issue legal advice, exercise licensed discretion, determine rights or breaches, or represent yourself as the property manager if you are not authorized to do so."},{"type":"callout","title":"Local rules matter","text":"Residential tenancy, licensing, notices, bonds, entry, repairs, rent increases, applications, and disclosure rules vary across Australian states and territories and can change. Use the client''s current local SOPs and official state or territory sources before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Using one state''s process for another state","Giving tenants legal advice","Calling a routine admin decision a property-manager decision or vice versa","Changing notice wording from memory","Using generic online templates instead of agency-approved forms"]},{"type":"scenario","title":"Practice scenario","text":"A portfolio covers NSW and QLD properties. A tenant asks how much notice the agency legally must give for entry. Explain how a VA routes the question instead of quoting a rule from memory."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Know the jurisdiction.","Use agency SOPs.","Keep legal interpretation local.","Document authority clearly."]}]'::jsonb,30,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='property-management-administration-australia') and position=1),'owner-tenant-property-and-privacy-data-administration','Owner, Tenant, Property, and Privacy Data Administration','Property-management systems hold identity, contact, financial, tenancy, property, access, maintenance, and sometimes sensitive personal information. Clean records help operations; broad access and careless sharing create risk.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Maintain core property records","Protect tenant and owner information","Resolve duplicates and conflicting details safely"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Property-management systems hold identity, contact, financial, tenancy, property, access, maintenance, and sometimes sensitive personal information. Clean records help operations; broad access and careless sharing create risk."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Property, owner, tenant, lease/tenancy, supplier, and contact records need stable identifiers.","Bank, identity, access-code, and application information are sensitive.","Source-of-truth fields should be defined.","Changes to owner payment/bank details are high risk.","Access information such as keys, alarm codes, and lockbox details should be tightly controlled."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Search before creating records.","Verify property and contact identity.","Update only from reliable authorized sources.","Use least-privilege access.","Keep access codes and identity documents out of open notes or chats.","Apply high-risk verification to owner/supplier bank changes.","Document material changes."]},{"type":"callout","title":"Stay inside the role","text":"Do not disclose tenant, owner, application, bank, or access information merely because someone knows the property address."},{"type":"callout","title":"Local rules matter","text":"Residential tenancy, licensing, notices, bonds, entry, repairs, rent increases, applications, and disclosure rules vary across Australian states and territories and can change. Use the client''s current local SOPs and official state or territory sources before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Merging tenants by name alone","Sending keys/access codes over insecure channels","Changing owner bank details from email only","Storing application IDs in personal folders","Giving contractors unnecessary tenant information"]},{"type":"scenario","title":"Practice scenario","text":"Someone claiming to be an owner emails new bank details and asks you to update the payment account urgently. Describe the agency verification and escalation steps."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Identity before changes.","Use least privilege.","Protect access data.","Treat bank changes as high risk."]}]'::jsonb,30,2,false,1,null,null,now(),now())
