insert into public.training_modules (course_id,title,summary,position) values ((select id from public.training_courses where slug='property-management-administration-australia'),'Leasing and Rent Administration','Support applicants and payment workflows safely.',2) on conflict (course_id,position) do update set title=excluded.title,summary=excluded.summary,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='property-management-administration-australia') and position=2),'leasing-enquiries-applications-and-anti-discrimination-boundaries','Leasing Enquiries, Applications, and Anti-Discrimination Boundaries','Leasing administration may involve enquiries, inspections, applications, document collection, reference checks, and status updates. Screening and approval decisions must follow the agency''s lawful criteria and local requirements.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Support leasing intake consistently","Collect application information without inventing screening rules","Communicate status without promising approval"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Leasing administration may involve enquiries, inspections, applications, document collection, reference checks, and status updates. Screening and approval decisions must follow the agency''s lawful criteria and local requirements."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Applicants should be handled using consistent agency processes.","Protected attributes and discrimination rules create high risk for informal screening.","The VA may collect documents and complete approved checks.","Application approval belongs to authorized staff according to agency process.","Privacy and document retention rules apply."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Record the enquiry and property.","Provide approved inspection/application information.","Collect only required documents.","Check completeness against the agency checklist.","Record approved reference-check outcomes factually.","Route application to responsible decision-maker.","Send status only after confirmed decision."]},{"type":"callout","title":"Stay inside the role","text":"Do not create your own applicant ranking, reject someone based on personal assumptions, promise approval, or provide legal interpretations of eligibility or discrimination law."},{"type":"callout","title":"Local rules matter","text":"Residential tenancy, licensing, notices, bonds, entry, repairs, rent increases, applications, and disclosure rules vary across Australian states and territories and can change. Use the client''s current local SOPs and official state or territory sources before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Writing subjective notes such as ''bad fit''","Collecting unnecessary sensitive information","Telling an applicant they are approved before confirmation","Using social media to screen applicants outside process","Applying inconsistent criteria"]},{"type":"scenario","title":"Practice scenario","text":"Two applicants are complete. A colleague asks you which one ''looks safer'' based on personal details. Explain the correct administrative response."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Use consistent criteria.","Collect only required data.","Keep approval with authorized staff.","Write factual notes."]}]'::jsonb,30,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='property-management-administration-australia') and position=2),'rent-arrears-receipts-and-financial-administration','Rent, Arrears, Receipts, and Financial Administration','Rent administration requires accurate ledgers and clear escalation because payment, arrears, receipts, trust/accounting processes, and formal notices can have legal consequences.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Support rent-payment administration","Identify arrears exceptions","Separate ledger work from trust, notice, and legal decisions"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Rent administration requires accurate ledgers and clear escalation because payment, arrears, receipts, trust/accounting processes, and formal notices can have legal consequences."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Payment status should come from the property-management/accounting system and evidence.","Arrears communication and formal notices may be governed by local rules.","Rent increases and adjustments require authorized workflows.","Trust-account handling can be regulated.","Payment plans, waivers, and legal enforcement are not routine VA decisions."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Review the rent or ledger status.","Check recent receipts and allocation.","Identify genuine overdue amounts under system rules.","Prepare the approved arrears queue.","Use only approved routine reminder wording.","Escalate formal notice, dispute, payment-plan, trust, or legal action questions.","Record the outcome."]},{"type":"callout","title":"Stay inside the role","text":"Do not decide when to issue statutory notices, alter rent, waive arrears, create payment plans, handle trust money outside approved controls, or give tenancy advice."},{"type":"callout","title":"Local rules matter","text":"Residential tenancy, licensing, notices, bonds, entry, repairs, rent increases, applications, and disclosure rules vary across Australian states and territories and can change. Use the client''s current local SOPs and official state or territory sources before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Sending an arrears message before checking recent payment","Quoting legal notice periods from memory","Changing rent values without approval","Applying payments to the wrong tenancy","Treating a dispute as ordinary debt collection"]},{"type":"scenario","title":"Practice scenario","text":"The ledger shows arrears, but the tenant sends a bank receipt from yesterday. Explain the checks before any formal or routine follow-up."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Payment status needs evidence.","Local notice rules require authorized process.","Keep trust and legal decisions controlled.","Document disputes."]}]'::jsonb,30,2,false,1,null,null,now(),now())
