insert into public.training_modules (course_id,title,summary,position) values ((select id from public.training_courses where slug='property-management-administration-australia'),'Maintenance and Access','Coordinate properties without making technical or legal decisions.',3) on conflict (course_id,position) do update set title=excluded.title,summary=excluded.summary,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='property-management-administration-australia') and position=3),'maintenance-emergencies-contractors-and-owner-approvals','Maintenance, Emergencies, Contractors, and Owner Approvals','Maintenance is one of the busiest property-management workflows. The VA must distinguish routine coordination from possible emergencies, technical decisions, spending approval, and tenancy obligations.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Capture maintenance requests well","Use emergency escalation rules","Coordinate contractors and approvals"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Maintenance is one of the busiest property-management workflows. The VA must distinguish routine coordination from possible emergencies, technical decisions, spending approval, and tenancy obligations."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["The tenant''s description should be preserved.","Emergency/urgent definitions should come from agency local SOPs.","Contractors need approved scope, access, and contact details.","Owner approval limits should be documented.","Technical diagnosis and legal repair obligations require responsible professionals."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Record property, reporter, issue, timing, photos, and access availability.","Check the agency emergency rule.","Escalate safety/high-risk uncertainty immediately.","Create maintenance task.","Route owner/property-manager approval where required.","Coordinate approved contractor.","Track quote, booking, access, completion, invoice, and follow-up.","Keep tenant and owner updated with confirmed information."]},{"type":"callout","title":"Stay inside the role","text":"Do not diagnose trades issues, declare a property safe, approve spend beyond authority, or decide legal repair obligations from your own judgment."},{"type":"callout","title":"Local rules matter","text":"Residential tenancy, licensing, notices, bonds, entry, repairs, rent increases, applications, and disclosure rules vary across Australian states and territories and can change. Use the client''s current local SOPs and official state or territory sources before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Calling everything routine because the portfolio is busy","Approving a high quote","Sending contractor private tenant data unnecessarily","Closing a job when the contractor says ''attended'' but not ''completed''","Giving technical DIY instructions"]},{"type":"scenario","title":"Practice scenario","text":"A tenant reports water entering near a ceiling light and a contractor can attend immediately above the usual owner approval limit. Build the safe escalation and admin workflow."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Safety first.","Use the agency emergency process.","Respect spending limits.","Track completion evidence."]}]'::jsonb,30,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='property-management-administration-australia') and position=3),'inspections-access-notices-and-calendar-coordination','Inspections, Access, Notices, and Calendar Coordination','Routine inspections, repairs, valuations, open homes, and other property access can involve notice requirements, tenant availability, contractor access, keys, travel, and local law. Scheduling must follow the agency''s approved jurisdiction-specific process.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Coordinate property access accurately","Use approved notice templates and timing","Protect keys and access information"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Routine inspections, repairs, valuations, open homes, and other property access can involve notice requirements, tenant availability, contractor access, keys, travel, and local law. Scheduling must follow the agency''s approved jurisdiction-specific process."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Entry/notice rules vary by state, territory, and purpose.","The VA can prepare and track approved notices but should not interpret legal sufficiency.","Calendar availability alone does not establish lawful access.","Keys, lockboxes, and alarm codes are sensitive.","Completed access should be recorded."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Identify the property jurisdiction and access purpose.","Use the agency''s current approved notice workflow.","Confirm responsible approver where required.","Track sent/served status from the agency process.","Schedule staff or contractor.","Share access details securely and minimally.","Record completion, no-access, reschedule, or exception."]},{"type":"callout","title":"Stay inside the role","text":"Do not decide that entry is legally permitted, shorten notice from memory, or force access when the tenant raises a dispute. Escalate to the local property manager."},{"type":"callout","title":"Local rules matter","text":"Residential tenancy, licensing, notices, bonds, entry, repairs, rent increases, applications, and disclosure rules vary across Australian states and territories and can change. Use the client''s current local SOPs and official state or territory sources before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Using one state''s notice template everywhere","Treating calendar booking as tenant consent","Putting lockbox codes in open notes","Rescheduling without updating notice requirements","Advising the tenant on their legal rights"]},{"type":"scenario","title":"Practice scenario","text":"A contractor wants to move a repair visit forward by two days, but the original access notice was for the later date. Explain the admin checks before confirming the change."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Jurisdiction matters.","Use approved notices.","Protect access information.","Escalate disputed entry."]}]'::jsonb,30,2,false,1,null,null,now(),now())
