insert into public.training_modules (course_id,title,summary,position) values ((select id from public.training_courses where slug='property-management-administration-australia'),'Renewals, Vacates, and Simulation','Track end-to-end portfolio administration.',4) on conflict (course_id,position) do update set title=excluded.title,summary=excluded.summary,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='property-management-administration-australia') and position=4),'renewals-vacates-bonds-and-handover-administration','Renewals, Vacates, Bonds, and Handover Administration','Lease/tenancy renewal and vacate workflows involve dates, documents, inspections, keys, cleaning, utilities, rent, repairs, and bond/deposit processes that may have legal requirements.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Track renewal and vacate milestones","Coordinate move-out administration","Keep bond and legal decisions with authorized staff"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Lease/tenancy renewal and vacate workflows involve dates, documents, inspections, keys, cleaning, utilities, rent, repairs, and bond/deposit processes that may have legal requirements."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Renewal decisions come from owner/property-manager process.","Notice and agreement documents are jurisdiction-specific.","Vacate requires clear dates, key return, inspection, outstanding work, and account status.","Bond/deposit release or claims can be regulated.","Evidence should be stored with the tenancy record."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Create the renewal/vacate checklist.","Track owner/manager decisions.","Use approved forms and notices.","Confirm move-out date and key-return process.","Coordinate final inspection/admin tasks.","Track outstanding invoices, rent, maintenance, and cleaning evidence.","Route bond/deposit decisions and disputes to authorized staff.","Archive after completion."]},{"type":"callout","title":"Stay inside the role","text":"Do not determine bond deductions, statutory notice validity, tenancy termination rights, rent increases, or dispute outcomes."},{"type":"callout","title":"Local rules matter","text":"Residential tenancy, licensing, notices, bonds, entry, repairs, rent increases, applications, and disclosure rules vary across Australian states and territories and can change. Use the client''s current local SOPs and official state or territory sources before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Promising full bond return","Sending non-approved notice wording","Missing key-return evidence","Deleting inspection photos","Closing the tenancy with unresolved account items"]},{"type":"scenario","title":"Practice scenario","text":"After vacate, the owner wants to deduct cleaning costs from the bond. Explain what the VA can prepare and what decision must remain with authorized property-management staff under local process."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Track milestones.","Preserve evidence.","Use approved forms.","Keep bond/legal decisions controlled."]}]'::jsonb,30,1,false,1,null,null,now(),now())
