insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='property-management-administration-australia') and position=4),'property-management-australia-composite-simulation','Property Management Australia Composite Simulation','This simulation combines leasing, rent, maintenance, access, privacy, renewals, and owner/tenant communication across a fictional portfolio.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Prioritize a mixed property-management queue","Recognize jurisdiction-sensitive decisions","Produce a property-manager-ready handoff"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"This simulation combines leasing, rent, maintenance, access, privacy, renewals, and owner/tenant communication across a fictional portfolio."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Leasing","Privacy","Rent administration","Maintenance","Access","Renewals/vacates","Local legal boundaries"]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Review the fictional queue.","Identify safety and high-risk privacy items.","Complete routine leasing and record tasks.","Prepare rent and maintenance exceptions.","Handle access scheduling under approved process.","Prepare renewal/vacate actions.","Write the handoff with jurisdiction and decision owners."]},{"type":"callout","title":"Stay inside the role","text":"Do not issue legal advice, interpret tenancy law, make applicant decisions, determine bond claims, approve unauthorized spend, or issue statutory notices from memory."},{"type":"callout","title":"Local rules matter","text":"Residential tenancy, licensing, notices, bonds, entry, repairs, rent increases, applications, and disclosure rules vary across Australian states and territories and can change. Use the client''s current local SOPs and official state or territory sources before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Using generic Australian rules instead of local state process","Treating applicant judgment as admin","Sending arrears before checking receipts","Ignoring possible emergencies","Giving tenants legal advice"]},{"type":"scenario","title":"Practice scenario","text":"A fictional portfolio includes an applicant query, a possible arrears mismatch, an urgent maintenance report, an inspection reschedule, an owner bank-detail change, and a bond deduction request. Build the safe work queue and handoff."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Always know the jurisdiction.","Use agency-approved SOPs.","Keep evidence and privacy strong.","Escalate legal and licensed decisions."]}]'::jsonb,30,2,false,1,null,null,now(),now())
